import { spawn } from 'node:child_process';

const bin = '/harness-state/.bun/bin/gbrain';
const child = spawn(bin, ['serve', '--surface', 'starter', '--advertise', 'verbs'], {
  env: { ...process.env, GBRAIN_HOME: '/harness-state' },
  stdio: ['pipe', 'pipe', 'pipe'],
});

let buf = '';
const pending = new Map();
const stderr = [];
child.stderr.on('data', (d) => stderr.push(d.toString()));

child.stdout.on('data', (d) => {
  buf += d.toString();
  let idx;
  while ((idx = buf.indexOf('\n')) >= 0) {
    const line = buf.slice(0, idx).trim();
    buf = buf.slice(idx + 1);
    if (!line) continue;
    let msg;
    try { msg = JSON.parse(line); } catch { continue; }
    if (msg.id && pending.has(msg.id)) {
      pending.get(msg.id)(msg);
      pending.delete(msg.id);
    }
  }
});

let nextId = 1;
function rpc(method, params) {
  const id = nextId++;
  return new Promise((resolve, reject) => {
    pending.set(id, resolve);
    child.stdin.write(JSON.stringify({ jsonrpc: '2.0', id, method, params }) + '\n');
    setTimeout(() => reject(new Error('timeout ' + method)), 60000);
  });
}
function notify(method, params) {
  child.stdin.write(JSON.stringify({ jsonrpc: '2.0', method, params }) + '\n');
}

try {
  const init = await rpc('initialize', {
    protocolVersion: '2024-11-05',
    capabilities: {},
    clientInfo: { name: 'openclaw-verify', version: '1.0.0' },
  });
  console.log('INIT server:', JSON.stringify(init.result?.serverInfo ?? init));
  notify('notifications/initialized', {});

  const list = await rpc('tools/list', {});
  const names = (list.result?.tools ?? []).map((t) => t.name);
  console.log('TOOLS:', names.join(', '));

  const remember = await rpc('tools/call', {
    name: 'remember',
    arguments: {
      claim: 'OpenClaw agent "main" has gbrain MCP memory wired on host dae613c31396 as of 2026-11-18',
      provenance: 'install-check',
      content_origin: 'agent_wrote',
    },
  });
  console.log('REMEMBER:', JSON.stringify(remember.result ?? remember).slice(0, 1200));

  const recall = await rpc('tools/call', {
    name: 'recall',
    arguments: { query: 'gbrain MCP memory wired OpenClaw main' },
  });
  console.log('RECALL:', JSON.stringify(recall.result ?? recall).slice(0, 2000));
} catch (e) {
  console.log('ERROR', e.message);
} finally {
  child.kill();
  if (stderr.length) console.log('STDERR:', stderr.join('').slice(0, 800));
}

